export const source = "Declare Function BuildSQLText PeopleCode FUNCLIB_TL_TA.TL_GEN_SQL FieldFormula;\n\nGlobal array of array of Record &PARENTBINDARRAY;\nGlobal number &SubQrylevel;\nGlobal boolean &ArrayCreated;\nGlobal boolean &CalledFromUpdate;\n\nLocal string &CRLF;\n\n&PARENTBINDARRAY = Null;\n&SubQrylevel = 0;\n&ArrayCreated = False;\n&CalledFromUpdate = False;\n\nrem Carriage Return, Line Feed;\n&CRLF = Char(13) | Char(10);\n\n/*****************************************************************************/\nrem Build label, build text, then open secondary page without standard page heading;\n/*****************************************************************************/\n\nDERIVED_TL_TA.RULE_TEXT.Label = TL_RULE_STEPS.TL_RULE_ID.GetShortLabel(\"TL_RULE_ID\") | \": \" | TL_RULE_DEFN.TL_RULE_ID.Value | \" - \" | TL_RULE_DEFN.DESCR.Value | &CRLF | TL_RULE_STEPS.TL_RULE_STEP.GetLongLabel(\"TL_RULE_STEP\") | \": \" | TL_RULE_STEPS.TL_RULE_STEP.Value;\n\nDERIVED_TL_TA.RULE_TEXT.Value = \"-- \" | TL_RULE_STEPS.SQL_ID.GetLongLabel(\"SQL_ID\") | \": \" | TL_RULE_STEPS.SQL_ID.Value | &CRLF | \"-- \" | TL_RULE_STEPS.DESCR100.GetLongLabel(\"DESCR100\") | \": \" | TL_RULE_STEPS.DESCR100.Value | &CRLF;\nDERIVED_TL_TA.RULE_TEXT.Value = DERIVED_TL_TA.RULE_TEXT.Value | &CRLF | BuildSQLText(TL_RULE_STEPS.SQL_ID.Value);\n\nDoModal(Page.TL_RULE_TEXT_SP, \" \", - 1, - 1);\n";
